os.makedirs(OUT, exist_ok=True)
P={}
def add(cid, pred, basis, conf, cm, ru, disp, reason):
    P[cid]={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,
            "trigger":{"changed_main":cm,"reserve_used":ru,"disputed":disp,"reason":reason}}

# trigger interpretation (no written definition in method text; stated per-case):
# changed_main = moving-line transformation (动化) overturns the initial static/main reading
# reserve_used = a reserve source (伏神/变爻代用 etc.) had to be used for the main or key auxiliary god
# disputed = contested selection / conflicting signals / damaged or contradictory chart data

